const fortunes = {
  '그냥 궁금해요': {title:'작은 좋은 일은,<br>생각보다 가까이에.', body:'오늘 하루를 전부 잘 보낼 필요는 없어요. 마음에 드는 순간 하나만 발견해도 충분해요. 익숙한 길에서 좋아하는 풍경을 한 번 더 바라봐요.',color:'버터 옐로',item:'좋아하는 노래 한 곡',action:'오늘 좋았던 순간을 사진 한 장으로 남겨보세요.',relation:'안부가 떠오르는 사람에게 짧은 인사를 건네봐요. 거창한 이야기가 아니어도 괜찮아요.'},
  '나만 늦은 것 같아': {title:'내 속도로 가도,<br>도착하는 곳은 있어요.',body:'다른 사람의 좋은 소식이 내 마감일은 아니에요. 지금까지 해온 일도, 잠시 쉬어가는 시간도 내 삶의 일부예요. 오늘은 비교 대신 나에게 시선을 돌려봐요.',color:'새싹 그린',item:'작은 노트',action:'최근에 내가 해낸 일 하나를 적어보세요. 아주 작은 일도 좋아요.',relation:'다른 사람의 속도에 맞추느라 힘들다면 오늘은 잠깐 소식을 쉬어가도 괜찮아요.'},
  '관계가 신경 쓰여': {title:'모든 마음을<br>맞힐 필요는 없어요.',body:'답장의 길이나 말투만으로 마음을 전부 알 수는 없어요. 오늘은 혼자 해석하는 시간을 조금 줄이고, 내가 원하는 것을 다정하게 말해봐요.',color:'체리 핑크',item:'따뜻한 차',action:'“왜 그랬어?” 대신 “나는 이렇게 느꼈어”로 한 문장을 시작해보세요.',relation:'상대의 마음은 추측보다 대화로 알아가요. 지금 당장 결론을 내리지 않아도 돼요.'},
  '일이 조금 버거워': {title:'오늘은 조금<br>덜 떠안아도 돼요.',body:'잘하고 싶은 마음이 할 일을 자꾸 늘릴 때가 있어요. 오늘의 할 일 중 꼭 필요한 하나만 먼저 골라봐요. 남겨둔 일이 나의 가치를 정하지는 않아요.',color:'스카이 블루',item:'편안한 운동화',action:'오늘 꼭 끝낼 일 하나와 내일 해도 되는 일 하나를 나눠 적어보세요.',relation:'부탁을 받으면 바로 답하기 전에 내 일정을 먼저 확인해도 괜찮아요.'}
};
const letters = [
  {icon:'✉',name:'결과를 기다리고 있어요',sub:'답이 오기 전, 오늘의 나에게',title:'답을 기다리는 동안에도,<br>당신의 하루는 소중해요.',body:'자꾸 날짜를 세게 되는 날이 있죠.\n다른 일을 하다가도 마음이 다시 그곳으로 돌아가고요.\n\n아직 모르는 결과를 오늘 다 감당하려고 애쓰지 않아도 돼요. 어떤 결과일지 여기서 약속할 수는 없지만, 지금 힘든 마음을 숨길 필요는 없어요.\n\n오늘은 기다리는 일 밖에 있는 작은 시간을 하나 골라보면 어떨까요. 익숙한 드라마 한 편, 잠깐의 산책, 편한 사람과 먹는 저녁 같은 것들이요.\n\n그것도 버거운 날이라면, 그냥 쉬어도 괜찮아요.'},
  {icon:'❀',name:'주변의 좋은 소식이 힘들어요',sub:'축하와 서운함이 함께 드는 날',title:'두 가지 마음이<br>함께 있어도 괜찮아요.',body:'누군가의 소식을 축하하면서도 내 상황이 서러울 수 있어요. 그 마음 때문에 나를 나쁜 사람으로 만들지 않았으면 해요.\n\n오늘 당장 밝은 답장을 보내거나 모임에 참석하지 않아도 괜찮아요. 마음을 추스를 시간을 가져도 돼요.\n\n필요하다면 이렇게 말해볼 수 있어요.\n“소식 전해줘서 고마워. 지금은 내 마음을 돌볼 시간이 조금 필요해서, 나중에 다시 연락할게.”\n\n다른 사람을 아끼는 마음만큼 내 마음도 아껴주세요.'},
  {icon:'♡',name:'배우자에게 말하기 어려워요',sub:'해결보다 함께 있어주길 바랄 때',title:'정답보다,<br>곁이 필요한 날이 있어요.',body:'같은 시간을 보내도 서로의 마음이 항상 같지는 않을 수 있어요. 어떤 위로를 원하는지 말로 꺼내기 어려운 날도 있고요.\n\n이 문장을 내 말투로 바꿔보세요.\n“오늘은 해결책을 찾기보다 내 이야기를 잠깐 들어줬으면 좋겠어. 나도 내 마음이 잘 정리되지 않아서 그래.”\n\n원하는 도움이 있다면 작게, 구체적으로 부탁해도 좋아요. 함께 저녁을 먹거나, 다음 일정에 동행해 달라고요.\n\n모든 마음을 한 번의 대화로 설명하지 않아도 괜찮아요.'},
  {icon:'☁',name:'오늘은 질문을 쉬고 싶어요',sub:'걱정해주는 말도 버거운 날',title:'말하지 않을 마음도<br>존중받아야 하니까요.',body:'관심에서 시작된 질문도 때로는 무겁게 느껴질 수 있어요. 내 상황을 매번 설명해야 할 의무는 없어요.\n\n이렇게 전해봐도 괜찮아요.\n“걱정해주는 마음은 고마워. 소식이 생기면 내가 먼저 이야기할게. 당분간은 묻지 않고 평소처럼 대해주면 좋겠어.”\n\n오늘은 다른 이야기를 해도 좋아요. 맛있었던 음식, 재미있게 본 영화, 아무 의미 없는 수다도요.\n\n나에게는 기다리는 일 말고도 많은 모습이 있으니까요.'}
];
function cards(){return `<div class="stories-grid"><a class="story-card" href="#compat"><div class="card-art pink"><span class="art-tag">RELATIONSHIP</span>${pairArt}</div><div class="card-content"><h3>우리 둘, 어떨까?</h3><p>만나기 전 살짝 궁금한<br>두 사람의 다른 점, 닮은 점.</p><div class="card-bottom"><span>궁합 미리보기 · 무료 시작</span><span>↗</span></div></div></a><a class="story-card" href="#work"><div class="card-art yellow"><span class="art-tag">MY NEXT CHAPTER</span>${workArt}</div><div class="card-content"><h3>나의 다음 챕터</h3><p>계속할까, 바꿔볼까?<br>내 속도로 찾는 다음 한 걸음.</p><div class="card-bottom"><span>일과 나 · 무료 읽기</span><span>↗</span></div></div></a><a class="story-card" href="#daily"><div class="card-art blue"><span class="art-tag">A LITTLE PAUSE</span>${moonArt}</div><div class="card-content"><h3>오늘은 나부터</h3><p>복잡한 마음은 잠깐 내려놓고<br>나를 위한 이야기 한 조각.</p><div class="card-bottom"><span>오늘의 마음 뽑기 · 무료</span><span>↗</span></div></div></a></div>`;}
function home(){return `<section class="greeting"><div><span class="eyebrow">YOUR DAILY LITTLE CORNER</span><h1>${username?esc(username)+'님, ':''}오늘은 조금, 마음 편하게.</h1></div><span class="date-label"><i></i>${today}</span></section><section class="hero"><div class="hero-copy"><span class="label-pill">✦ 하루 한 번, 작은 행운</span><h2>좋은 일이 올 것 같은<br><em>그런 기분이 필요할 때.</em></h2><p>버튼 한 번, 오늘의 나를 위한 이야기.<br>어쩌면 지금 듣고 싶었던 말일지도 몰라요.</p><a class="primary" href="#daily">오늘의 행운 뽑기 <span>↗</span></a><small class="hero-note">무료예요. 가벼운 마음만 챙겨오세요.</small></div><div class="machine-scene"><span class="spark">✧</span><div class="machine">${machine}</div><span class="float-stamp">a little<br>luck for you</span><span class="spark two">✦</span></div></section><div class="mini-strip"><span class="clover">✿</span><span>오늘의 한마디 <b>“다른 사람의 속도가 내 마감일은 아니에요.”</b></span><a href="#daily">내 이야기 보기 ↗</a></div><section><div class="section-heading"><div><h2>요즘, 뭐가 마음에 걸려요?</h2><p>혼자 생각하던 것들, 여기서 가볍게 펼쳐봐요.</p></div><a href="#stories">모두 보기 ↗</a></div>${cards()}</section><section class="letter-banner"><div class="envelope-art">${envelope}</div><div><small>A LETTER, JUST FOR YOU</small><h2>기다리는 마음에게</h2><p>아직 오지 않은 답을 기다리는 당신에게.<br>예측 대신, 오늘을 함께하는 작은 편지.</p></div><a href="#letters">조용히 들러보기 ↗</a></section><p class="bottom-note"><span>✳</span> 조금 느린 날도, 괜찮은 날이니까. <span>✳</span></p>`;}
function heading(label,title,body){return `<div class="page-head"><span class="eyebrow">${label}</span><h1>${title}</h1><p>${body}</p></div>`;}
function daily(){return `${heading('A LITTLE LUCK','오늘, 어떤 마음으로 왔어요?','지금 마음에 가까운 하나를 골라주세요. 작은 이야기를 꺼내드릴게요.')}<section class="draw-layout"><div class="draw-visual"><div class="machine">${machine}</div></div><div class="content-panel draw-copy"><span class="label-pill">✦ 오늘의 마음 뽑기</span><h2 style="margin-top:16px">마음부터 살짝,<br>들여다볼까요?</h2><div class="chips">${Object.keys(fortunes).map(x=>`<button class="chip ${x===mood?'selected':''}" data-mood="${x}" aria-pressed="${x===mood}">${x}</button>`).join('')}</div><p>좋고 나쁨을 매기는 점수 대신,<br>오늘 나에게 필요한 문장 하나.</p><button class="primary full" data-action="draw">내 이야기 뽑기 ✦</button><p class="small-print">선택한 마음에 맞춘 예시 콘텐츠예요.<br>미래를 예측하는 결과가 아니에요.</p></div></section>`;}
function result(){const r=currentResult||fortunes[mood];currentResult=r;return `<a href="#daily" class="back-link">← 다른 마음 고르기</a><section class="result-card"><span class="result-meta">${today} · 오늘의 마음편</span><div class="result-symbol">✿</div><h2>${r.title}</h2><p>${r.body}</p><div class="lucky-row"><div><small>오늘의 컬러</small><b>${r.color}</b></div><div><small>작은 즐거움</small><b>${r.item}</b></div></div></section><div class="result-actions"><button class="primary" data-action="save-result">내 서랍에 담기 ♡</button><button class="secondary" data-action="share">친구에게 보내기 ↗</button></div><div class="detail-stack"><details open><summary>✦ 오늘 해볼 작은 일</summary><p>${r.action}</p></details><details><summary>♡ 사람 사이, 오늘의 한마디</summary><p>${r.relation}</p></details><p class="small-print">오늘 선택한 마음을 위한 가벼운 읽을거리예요. 같은 마음을 고르면 같은 카드가 나와요.</p></div>`;}
function compat(){return `${heading('A LITTLE CHEMISTRY','우리 둘, 어떨까?','궁금한 마음은 가볍게. 서로를 알아가는 대화는 조금 더 깊게.')}<div class="compat-layout"><div class="compat-intro"><div class="card-art">${pairArt}</div><h2>닮아서 좋은 것,<br>달라서 궁금한 것.</h2><p>혼자 먼저 살펴봐도 괜찮아요.<br>두 사람의 이야기를 시작할 질문을 만나보세요.</p><p class="small-print">이번 시안은 관계 단계에 맞춘 예시 리포트예요. 생년월일을 수집하거나 실제 사주를 계산하지 않아요.</p></div><form id="compat-form" class="content-panel form-stack"><fieldset><legend>01. 두 사람을 어떻게 부를까요?</legend><div class="form-row"><div><label for="my-name">내 별명</label><input id="my-name" name="me" maxlength="12" placeholder="예: 나" required autocomplete="off"></div><div><label for="their-name">상대 별명</label><input id="their-name" name="them" maxlength="12" placeholder="예: 궁금한 그 사람" required autocomplete="off"></div></div></fieldset><fieldset><legend>02. 지금 두 사람은?</legend><label for="stage">관계 단계</label><select name="stage" id="stage"><option value="before">만나기 전, 소개받았어요</option><option value="dating">조금씩 알아가는 중이에요</option><option value="together">함께하는 미래가 궁금해요</option></select></fieldset><p class="small-print">별명은 결과를 부르는 데만 사용해요. 이 입력은 서버에 보내거나 저장하지 않아요.</p><button type="submit" class="primary full">무료 미리보기 열기 ↗</button></form></div>`;}
const pairReadings = {
 before:{title:'정답을 찾기보다,<br>서로의 일상을 궁금해하기.',intro:'첫 만남에는 잘 맞는 사람인지 빨리 알고 싶어져요. 공통점의 개수보다 서로의 이야기를 편하게 듣고 있는지 살펴봐도 좋아요.',question:'“쉬는 날은 미리 계획하는 편이에요, 그날 마음 가는 대로 보내는 편이에요?”',sections:[['연락의 속도','연락 횟수만으로 관심을 단정하지 말고, 평소의 생활 리듬을 물어보세요. 내가 편한 연락 방식도 함께 말해볼 수 있어요.'],['생활의 모양','주말을 보내는 방식, 혼자 있는 시간, 좋아하는 식사를 이야기해보세요. 작은 취향을 통해 대화가 자연스럽게 이어질 수 있어요.'],['첫 만남의 질문','요즘 가장 즐거웠던 일은 무엇인가요? · 바쁜 날에는 어떻게 쉬나요? · 친구와 주로 무엇을 하나요? · 새로운 곳과 익숙한 곳 중 어디를 좋아하나요? · 다음에 함께 해보고 싶은 게 있나요?']]},
 dating:{title:'다른 마음의 속도도,<br>대화로 맞춰갈 수 있어요.',intro:'조금씩 가까워질수록 기대도 함께 생겨요. 혼자 만든 규칙에 상대를 맞추기보다 서로에게 편안한 방식을 이야기해봐요.',question:'“바쁜 날에는 어떤 식으로 연락하면 서로 편할까?”',sections:[['표현의 방식','말로 듣는 표현과 행동으로 느끼는 표현 중 무엇이 반가운지 이야기해보세요. 내가 필요한 표현을 구체적으로 말하는 것도 좋아요.'],['서운함을 나누는 법','“늘 그렇잖아”보다 한 장면과 내 마음을 설명해보세요. 당장 대화하기 어렵다면 다시 이야기할 시간을 함께 정할 수 있어요.'],['서로 알아갈 질문','어떤 순간에 사랑받는다고 느끼나요? · 혼자 쉬고 싶을 땐 어떻게 알려줄까요? · 다툰 후 무엇이 도움이 되나요? · 함께 만들고 싶은 습관은 무엇인가요? · 요즘 내게 고마웠던 일은 있나요?']]},
 together:{title:'같은 미래에도,<br>서로의 설명이 필요해요.',intro:'함께하고 싶은 마음과 실제 생활의 계획은 차근차근 나눠볼 수 있어요. 한 번에 결론을 내기보다 중요한 주제부터 하나씩 꺼내봐요.',question:'“우리에게 편안한 일주일은 각각 어떤 모습일까?”',sections:[['생활과 책임','집안일과 쉬는 시간에 대해 막연히 반씩이라고 생각하기보다 어떤 일을 어떻게 맡을지 구체적으로 이야기해보세요.'],['돈과 가족의 경계','함께 쓰는 비용과 각자 쓰는 비용, 가족과의 시간에 대해 서로의 기대를 들어보세요. 같은 답보다 이야기할 수 있는 분위기가 먼저예요.'],['미래를 위한 질문','살고 싶은 생활은 어떤 모습인가요? · 각자의 시간은 얼마나 필요한가요? · 중요한 지출은 어떻게 정할까요? · 가족과의 일정은 어떻게 조율할까요? · 계획이 달라질 때 어떻게 다시 이야기할까요?']]}
};
function compatibilityResult(){if(!pair)return compat();const r=pairReadings[pair.stage];return `<a href="#compat" class="back-link">← 다시 입력하기</a><section class="compat-result"><div class="result-card"><span class="result-meta">${esc(pair.me)} & ${esc(pair.them)} · 관계 이야기</span><div style="height:150px">${pairArt}</div><h2>${r.title}</h2><p>${r.intro}</p></div><div class="reading-block"><h3>먼저 꺼내볼 질문 하나</h3><p>${r.question}</p></div>${pair.unlocked?`<div class="label-pill" style="margin-top:24px">전체 예시 열림 · 실제 결제 없음</div>${r.sections.map(s=>`<div class="reading-block"><h3>${s[0]}</h3><p>${s[1]}</p></div>`).join('')}`:`<div class="pay-card"><span class="eyebrow">A LITTLE MORE ABOUT US</span><h3>두 사람의 이야기를 더 펼쳐볼까요?</h3><ul>${r.sections.map(s=>`<li>${s[0]}</li>`).join('')}</ul><div class="pay-price"><strong>3,900원</strong><span>출시 가격 가안 · 단건</span></div><button class="primary full" data-action="checkout">전체 해석 체험하기 ↗</button><p class="small-print">현재는 시안입니다. 결제 없이 전체 예시를 확인할 수 있어요.</p></div>`}<p class="small-print">관계 단계에 따라 제공되는 대화 가이드 예시입니다. 상대의 성격이나 안전성, 관계의 미래를 판정하는 결과가 아니에요.</p></section>`;}
function lettersPage(){return `<section class="letter-page">${heading('A QUIET PLACE FOR YOUR HEART','기다리는 마음에게','임신을 준비하거나, 아직 오지 않은 답을 기다리는 날.<br>좋은 결과를 약속하는 대신 오늘의 마음 곁에 있을게요.')}<div class="envelope-art" style="margin:20px auto">${envelope}</div><div class="letter-choice">${letters.map((l,i)=>`<button data-letter="${i}"><span>${l.icon}</span><b>${l.name}</b><small>${l.sub} ↗</small></button>`).join('')}</div><p class="small-print" style="text-align:center;margin-top:25px">설명하지 않아도, 기록하지 않아도 괜찮아요.<br>이 공간의 모든 편지는 무료예요.</p></section>`;}
function letterView(){const l=letters[currentLetter??0];return `<section class="letter-page"><a href="#letters" class="back-link">← 다른 편지 둘러보기</a><div class="letter-paper"><span class="eyebrow">A LETTER, JUST FOR YOU</span><h2>${l.title}</h2><p>${l.body}</p><p class="sign">오늘도 당신의 편에서, 마음편.</p></div><div class="result-actions"><button class="secondary" data-action="save-letter">내 서랍에 간직하기 ♡</button><a class="primary" href="#home">오늘은 여기까지</a></div><p class="small-print" style="text-align:center">결과나 시기를 예측하지 않는 마음 편지예요.<br>의학적 판단은 담당 의료진과 함께 확인해주세요.</p></section>`;}
function work(){return `${heading('MY NEXT CHAPTER','계속할까, 바꿔볼까?','오늘 당장 결론을 내리지 않아도 돼요. 작은 질문부터 시작해봐요.')}<div class="content-panel" style="max-width:680px;margin:auto"><div style="height:180px">${workArt}</div><div class="reading-block"><h3>지금 가장 버거운 건 무엇인가요?</h3><p>일 자체인지, 함께하는 사람인지, 일하는 환경인지 나눠 생각해봐요. 한 가지 문제가 모든 일의 문제로 느껴질 때가 있어요.</p></div><div class="reading-block"><h3>지키고 싶은 것도 있나요?</h3><p>지금의 일에서 잃고 싶지 않은 점을 하나 골라보세요. 안정적인 생활, 배우는 즐거움, 익숙한 동료. 다음 선택의 기준이 될 수 있어요.</p></div><div class="reading-block"><h3>이번 주에 할 수 있는 작은 실험</h3><p>관심 있는 일의 실제 하루를 알아보거나, 해본 사람에게 물어보거나, 짧은 시간을 내어 직접 해보세요. 결심 전에 정보를 하나 더 얻어도 좋아요.</p></div><a href="#daily" class="primary" style="margin-top:24px">오늘의 나를 위한 한마디 ↗</a></div>`;}
function savedPage(){return `${heading('MY LITTLE DRAWER','내 작은 서랍','다시 읽고 싶은 말들을 여기 모아두었어요. 이 브라우저에만 저장돼요.')} ${saved.length?`<div class="saved-list">${saved.map((s,i)=>`<article class="saved-item"><small>${esc(s.date)} · ${esc(s.type)}</small><h2>${esc(s.title)}</h2><p>${esc(s.body)}</p><button data-remove="${i}">서랍에서 꺼내기</button></article>`).join('')}</div><button class="secondary" data-action="clear-saved" style="margin-top:20px">모두 비우기</button>`:`<div class="empty"><span>▱</span><h2>아직은 비어 있는 작은 서랍</h2><p>마음에 남는 오늘의 이야기나 편지를 간직해보세요.</p><a class="primary" href="#daily">첫 번째 이야기 만나기 ↗</a></div>`}`;}
function route(){clearTimeout(timer);const hash=location.hash.slice(1)||'home';const pages={home,stories:()=>`${heading('PICK YOUR STORY','요즘, 뭐가 마음에 걸려요?','지금 궁금한 이야기부터 가볍게 시작해요.')}${cards()}`,daily,result,compat,'compat-result':compatibilityResult,letters,letter:letterView,work,saved:savedPage};pages.letters=lettersPage;main.innerHTML=(pages[hash]||home)();main.classList.remove('fade-in');void main.offsetWidth;main.classList.add('fade-in');const nav=hash==='compat'||hash==='compat-result'||hash==='work'?'stories':hash==='letter'?'letters':hash==='daily'||hash==='result'?'home':hash;document.querySelectorAll('[data-nav]').forEach(a=>{a.classList.toggle('active',a.dataset.nav===nav);if(a.dataset.nav===nav)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});$('#save-count').textContent=saved.length;$('.profile').textContent=username?String(username).slice(0,1):'나';window.scrollTo(0,0);}
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('visible');clearTimeout(toast.timeout);toast.timeout=setTimeout(()=>$('#toast').classList.remove('visible'),2800);}
function modal(html){$('#dialog-body').innerHTML=html;$('#dialog').showModal();}
function addSaved(entry){if(saved.some(x=>x.title===entry.title&&x.type===entry.type)){toast('이미 서랍에 담아둔 이야기예요.');return;}const next=[{...entry,date:today},...saved];if(write('maeumpyeon.saved',next)){saved=next;$('#save-count').textContent=saved.length;toast('내 작은 서랍에 담았어요.');}}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action],[data-mood],[data-letter],[data-remove]');if(!b)return;if(b.dataset.mood){mood=b.dataset.mood;main.innerHTML=daily();return;}if(b.dataset.letter!==undefined){currentLetter=Number(b.dataset.letter);location.hash='letter';return;}if(b.dataset.remove!==undefined){const next=saved.filter((_,i)=>i!==Number(b.dataset.remove));if(write('maeumpyeon.saved',next)){saved=next;route();}return;}
 switch(b.dataset.action){
 case 'draw':b.disabled=true;b.textContent='당신의 이야기를 꺼내는 중…';$('.draw-visual').classList.add('drawing');timer=setTimeout(()=>{currentResult=fortunes[mood];location.hash='result';},850);break;
 case 'save-result':{const r=currentResult||fortunes[mood];addSaved({type:'오늘의 마음',title:r.title.replace(/<br>/g,' '),body:r.body});break;}
 case 'save-letter':{const l=letters[currentLetter??0];addSaved({type:'마음 편지',title:l.title.replace(/<br>/g,' '),body:l.body});break;}
 case 'share':{const r=currentResult||fortunes[mood];const text=`오늘의 마음편 🍀\n${r.title.replace(/<br>/g,' ')}\n\n${r.body}`;try{if(navigator.share){await navigator.share({title:'오늘의 마음편',text});}else{await navigator.clipboard.writeText(text);toast('카드 문장을 복사했어요. 친구에게 붙여넣어 보내세요.');}}catch(err){if(err.name!=='AbortError')modal(`<h2>오늘의 마음편 보내기</h2><p>아래 문장을 선택해 복사해주세요.</p><p style="white-space:pre-line;user-select:text">${esc(text)}</p>`);}break;}
 case 'checkout':modal('<span class="label-pill">결제 흐름 체험</span><h2 style="margin-top:16px">우리 둘 이야기, 전체 보기</h2><p>출시 가격 가안은 3,900원이에요. 이번 시안에서는 카드 정보나 결제 없이 전체 예시를 열어볼 수 있어요.</p><button class="primary full" data-action="unlock">결제 없이 전체 예시 보기</button>');break;
 case 'unlock':if(pair){pair.unlocked=true;$('#dialog').close();route();toast('전체 예시를 열었어요. 실제 결제는 발생하지 않았어요.');}break;
 case 'profile':modal(`<h2>어떻게 불러드릴까요?</h2><p>실명 대신 편한 별명을 써도 좋아요.<br>이 브라우저에만 저장해요.</p><form id="name-form"><label for="nickname">내 별명</label><input id="nickname" name="nickname" maxlength="12" value="${esc(username)}" placeholder="별명을 알려주세요" required><button class="primary full" type="submit">이 이름으로 불러줘요</button></form>`);break;
 case 'about':modal('<h2>오늘도, 내 마음 편.</h2><p>마음편은 작은 행운과 다정한 읽을거리로 잠깐 쉬어가는 공간이에요.</p><p>현재는 첫 번째 체험 시안이에요. 오늘의 카드는 선택한 마음별 예시이며, 궁합은 관계 단계별 대화 가이드입니다. 실제 사주 계산·AI 상담·결제 기능은 연결되지 않았어요.</p><p>별명과 담아둔 글은 이 브라우저에만 저장됩니다. 관계 입력은 화면에서만 사용하며, 새로고침하면 사라져요.</p><p>미래·임신 결과를 예측하거나 의료 판단을 제공하지 않아요.</p>');break;
 case 'clear-saved':modal('<h2>서랍을 비울까요?</h2><p>이 브라우저에 저장한 이야기와 편지가 모두 지워져요.</p><button class="primary full" data-action="confirm-clear">모두 지우기</button>');break;
 case 'confirm-clear':if(write('maeumpyeon.saved',[])){saved=[];$('#dialog').close();route();toast('서랍을 비웠어요.');}break;
 }
});
document.addEventListener('submit',e=>{if(e.target.id==='compat-form'){e.preventDefault();const fd=new FormData(e.target);const me=String(fd.get('me')).trim(),them=String(fd.get('them')).trim();if(!me||!them){toast('두 사람의 별명을 입력해주세요.');return;}pair={me,them,stage:fd.get('stage'),unlocked:false};location.hash='compat-result';}if(e.target.id==='name-form'){e.preventDefault();const name=String(new FormData(e.target).get('nickname')).trim();if(!name){toast('별명을 입력해주세요.');return;}if(write('maeumpyeon.name',name)){username=name;$('#dialog').close();route();toast('반가워요, '+name+'님.');}}});
$('.close-dialog').addEventListener('click',()=>$('#dialog').close());
$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog')){const r=$('#dialog').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#dialog').close();}});
window.addEventListener('hashchange',route);route();
